% Matthias Panny - 2026-09-08

clearvars
clc
%%
%[text] ## Signal
Ts = 1e-3;

A = 1.5;
f = 5;

t = 0:Ts:1;

y = A * sin(2*pi*f*t) + 0.005 * randn(size(t));
y_d_exact = 2*pi*f*A*cos(2*pi*f*t); %without noise

%%
%[text] ## Kernel
% Parameters
T = 5e-2;     % kernel window length
n = 4;        % kernel order
r_max = 4;    % max derivative order

% Base polynomial S(tau) for tau = t/T
max_order = 2*n + 1;

Cn = factorial(max_order)/(factorial(n)^2);
S_p = zeros(1, max_order + 1); % for polynomial of degree max_order

for k = 0:n
    % Coefficients for tau^(n+k+1) --> descending order
    i = max_order - (n+k+1) + 1;
    S_p(i) = Cn * nchoosek(n, k) * ((-1)^k/(n+k+1));
end

% Derivative polynomials phi(tau), scaled by 1/T^r for d/dt
% d^r/dt^r f(t/T) = (1/T^r) * d^r/dtau^r f(tau)
phi_polys = cell(r_max+1, 1);

% index 1 is already the smoothing kernel
% the prototype function is only available in S_p
phi_polys{1} = polyder(S_p);
for r = 1:r_max
    phi_polys{r+1} = polyder(phi_polys{r}) / T;
end

%%
%[text] ## Only evaluate kernel over \[0,T\]
tau = t ./ T;

idx = t <= T;
tau_kernel = tau(idx);
%%
%[text] ## Normalization
phi_0th_deriv = polyval(phi_polys{1}, tau_kernel);
norm_factor  = sum(phi_0th_deriv);
%%
%[text] ## Derivative Kernels
deriv_order = 1;
kernel_dot = polyval(phi_polys{deriv_order+1}, tau_kernel) / norm_factor;
%%
%[text] ## Apply first derivative kernel
y_d = conv(y, kernel_dot, "same");
y_d_diff = diff(y) / Ts;
%%
%[text] ## Plot
figure %[output:7d197344]
plot(t, y, 'DisplayName', 'y') %[output:7d197344]
hold on %[output:7d197344]
plot(t, y_d_exact, 'DisplayName', 'y'' exact') %[output:7d197344]
plot(t, y_d, 'DisplayName', 'y'' convolution') %[output:7d197344]
plot(t(1:end-1), y_d_diff, '--', 'DisplayName', 'y'' finite difference') %[output:7d197344]

fusion = 0.9*y_d + (1-0.9) * [y_d_diff, y_d_diff(end)];
plot(t, fusion, ':', 'DisplayName', 'y'' fusion') %[output:7d197344]

legend %[output:7d197344]
grid on %[output:7d197344]


figure %[output:0d3a9f97]
plot(t, (y_d_exact - y_d), 'DisplayName', 'abs. error'); %[output:0d3a9f97]
legend %[output:0d3a9f97]
grid on %[output:0d3a9f97]

